<script setup lang="ts">
import { watch } from 'vue';
import { useI18n } from 'vue-i18n';
import type { OnlineSchedulesStore } from '../../stores/onlineSchedules.js';
import OnlineDeliveryList from './OnlineDeliveryList.vue';
const props = defineProps<{ schedules: OnlineSchedulesStore }>();
const { t, te, locale } = useI18n();
const label = (code: string | null) => !code ? t('onlineExecution.notCollected') : te('scheduleDelivery.' + code) ? t('scheduleDelivery.' + code) : te('scheduleCodes.' + code) ? t('scheduleCodes.' + code) : te('onlineExecution.states.' + code) ? t('onlineExecution.states.' + code) : code;
const reason = (value: string) => { const safe = value.match(/(?:^|Error: )([a-z][a-z0-9_-]{0,95})$/)?.[1]; if (!safe) return t('scheduleEditor.requestFailed'); for (const namespace of ['scheduleCodes', 'onlineExecution.reasons', 'startRejectionLabels']) if (te(namespace + '.' + safe)) return t(namespace + '.' + safe); return safe; };
const time = (value: string | null) => value ? new Intl.DateTimeFormat(locale.value, { timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', fractionalSecondDigits: 3, hourCycle: 'h23' }).format(new Date(value)) + ' UTC' : t('onlineExecution.notCollected');
watch(() => [props.schedules.context, props.schedules.visible] as const, ([context, visible]) => { if (context && visible) void props.schedules.loadNotifications(); }, { immediate: true });
</script>
<template><section class="notifications"><header><p>{{ t('scheduleNotifications.scope') }}</p><button @click="schedules.loadNotifications()">{{ t('scheduleCenter.refresh') }}</button><button v-if="schedules.notifications?.nextBeforeId" data-testid="notification-more" @click="schedules.loadNotifications(schedules.notifications.nextBeforeId)">{{ t('schedulePagination.notifications') }}</button></header><p v-if="schedules.error" role="alert">{{ reason(schedules.error) }}</p><div class="event-scroll"><article v-for="event in schedules.notifications?.items ?? []" :key="event.id"><h3 :title="event.scheduleName">{{ event.scheduleName }}</h3><p :title="event.projectName">{{ event.projectName }} · #{{ event.scheduleId }}</p><p>{{ t('scheduleCenter.verdict', { value: event.verdict ? t('onlineExecution.states.' + event.verdict) : t('onlineExecution.notCollected') }) }}</p><dl><dt>{{ t('scheduleHistory.planned') }}</dt><dd><time :title="event.plannedAtUtc ?? undefined">{{ time(event.plannedAtUtc) }}</time></dd><dt>{{ t('scheduleHistory.actual') }}</dt><dd>{{ time(event.startedAtUtc) }}</dd><dt>{{ t('scheduleHistory.archive') }}</dt><dd>{{ t('onlineExecution.states.' + event.reportState) }}</dd><dt>{{ t('scheduleHistory.reason') }}</dt><dd>{{ reason(event.reasonCode) }}</dd></dl><p>{{ t(event.read ? 'scheduleCenter.read' : 'scheduleCenter.unread') }}</p><button v-if="!event.read" data-testid="notification-read" @click="schedules.markRead(event.id)">{{ t('scheduleCenter.markRead') }}</button><section><h4>{{ t('scheduleHistory.notification') }} · {{ label(event.notificationState) }}</h4><OnlineDeliveryList :deliveries="event.deliveries" /></section></article></div></section></template>
<style scoped>.notifications{height:100%;min-height:0;display:flex;flex-direction:column;overflow:hidden;padding:12px}.event-scroll{min-height:0;overflow:auto}article{border:1px solid var(--border);padding:12px;margin:10px 0;min-width:0}h3{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:6px 12px}dd{margin:0;overflow-wrap:anywhere}</style>
